function Avatar({name,avatar,size,className}){
  const initials=(name||'?').split(' ').map(w=>w[0]).join('').slice(0,2).toUpperCase();
  const sz=size||32;
  if(avatar){
    return h('div',{className:className||'avatar',style:{width:sz,height:sz,borderRadius:'50%',overflow:'hidden',flexShrink:0,border:'2px solid var(--border)'}},
      h('img',{src:avatar,style:{width:'100%',height:'100%',objectFit:'cover'},alt:name})
    );
  }
  return h('div',{className:className||'avatar',style:{width:sz,height:sz,fontSize:sz*0.35,flexShrink:0}},initials);
}


function Sidebar({page,setPage,user,t,onLogout,sidebarOpen,setSidebarOpen,notifications,quizActive}){
  const nav=(icon,label,id,badge)=>{
    const locked=quizActive&&id!=='quiz';
    return h('button',{key:id,className:'nav-item'+(page===id?' active':'')+(locked?' disabled':''),disabled:locked,onClick:()=>{if(locked)return;setPage(id);setSidebarOpen(false);playClick();}},icon,label,badge>0&&h('span',{className:'nav-badge'},badge));
  };
  const name=user&&user.name?user.name:'Guest';
  const initials=name.split(' ').map(w=>w[0]).join('').slice(0,2).toUpperCase()||'?';
  const lvl=getLevelInfo(user.xp||0);
  return h('aside',{className:'sidebar'+(sidebarOpen?' open':'')},
    h('div',{className:'sidebar-logo'},
      h('button',{className:'logo-mark',disabled:quizActive,onClick:()=>{if(quizActive)return;setPage('dashboard');setSidebarOpen(false);},style:{background:'none',border:'none',cursor:quizActive?'not-allowed':'pointer',padding:0,display:'flex',alignItems:'center',gap:'8px',overflow:'hidden',maxWidth:'100%',opacity:quizActive?.4:1}},h('img',{src:'data:image/png;base64,',style:{height:40,width:'auto',display:'block',flexShrink:0},alt:'QuizMaster'}),h('span',{style:{fontFamily:'var(--font-display)',fontWeight:800,fontSize:16,color:'#fff',letterSpacing:'-0.3px',whiteSpace:'nowrap'}},'QuizMaster')),
      h('button',{className:'sidebar-close-btn',onClick:()=>setSidebarOpen(false)},icons.xmark)
    ),
    h('nav',{className:'sidebar-nav'},
      h('div',{className:'nav-section'},h('div',{className:'nav-label'},t.main),nav(icons.home,t.dashboard,'dashboard'),nav(icons.quiz,t.quiz,'quiz'),nav(icons.trophy,t.leaderboard,'leaderboard'),nav(icons.chart,t.stats,'stats')),
      h('div',{className:'nav-section'},h('div',{className:'nav-label'},t.account),nav(icons.user,t.profile,'profile'),nav(icons.bell,t.notifications,'notifications',(notifications||[]).filter(n=>n.unread).length),nav(icons.settings,t.settings,'settings')),
      isAdminUser(user)&&h('div',{className:'nav-section'},h('div',{className:'nav-label'},t.manage),nav(icons.shield,t.admin,'admin'))
    ),
    h('div',{className:'sidebar-footer'},
      h('div',{className:'user-card'},
        h(Avatar,{name,avatar:user.avatar,size:32}),
        h('div',{className:'user-info'},h('div',{className:'user-name'},name),h('div',{className:'user-role'},'Lv '+lvl.level+' '+lvl.title+' · '+(user.xp||0)+' XP')),
        h('button',{style:{border:'none',background:'transparent',cursor:quizActive?'not-allowed':'pointer',color:'var(--text3)',flexShrink:0,opacity:quizActive?.4:1},disabled:quizActive,onClick:()=>{if(quizActive)return;onLogout();},title:t.logout},icons.logout)
      )
    )
  );
}

function TopBar({title,actions,onMenuClick,onBack}){
  return h('div',{className:'topbar'},
    h('button',{className:'hamburger',onClick:onMenuClick},icons.menu),
    onBack&&h('button',{className:'btn btn-ghost btn-sm',onClick:onBack,style:{flexShrink:0}},
      h('svg',{viewBox:'0 0 24 24',fill:'none',stroke:'currentColor',strokeWidth:2,strokeLinecap:'round',strokeLinejoin:'round',style:{width:16,height:16}},h('polyline',{points:'15 18 9 12 15 6'})),' Back'
    ),
    h('div',{className:'topbar-title'},title),
    h('div',{className:'topbar-spacer'}),
    actions&&h('div',{className:'topbar-actions'},actions)
  );
}

function HeroTyping(){
  return h('h1',{className:'hero-title'},
    'The smartest way to',
    h('br',null),
    h('span',{className:'grad'},'test your knowledge')
  );
}
